Below is a small, **clean and efficient** C++ program that reads two integers `n` and `r` (0 ≤ r ≤ n), computes the binomial coefficient  

\[
\binom{n}{r}=\frac{n!}{r!(n-r)!}
\]

and prints the result.  
The algorithm multiplies only `min(r, n‑r)` terms and divides by the denominator
term‑by‑term, which keeps the intermediate numbers far smaller than the full
factorials.  It also performs a GCD–based reduction after each multiplication
to keep the intermediate values in the 64‑bit range whenever possible.

You can easily tweak it to use big‑integer libraries (like `boost::multiprecision::cpp_int`)
if you need to handle astronomically large `n`’s.

```cpp
/*********************************************************************
 *  NCR (Binomial Coefficient) in C++
 *
 *  This program reads two integers n and r (0 ≤ r ≤ n) and prints
 *  the value of nCr.  It works for 64‑bit signed numbers and
 *  automatically uses the smaller of r and n‑r to minimise work.
 *
 *  Author : Your Name
 *  Date   : 2026‑07‑15
 *********************************************************************/

#include <bits/stdc++.h>
using namespace std;

//------------- Utility: greatest common divisor ------------------
static inline long long gcdll(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

//------------- nCr ------------------------------------------------
long long nCr(long long n, long long r) {
    if (r < 0 || r > n) return 0;
    r = min(r, n - r);              // exploit symmetry

    long long result = 1;
    for (long long i = 1; i <= r; ++i) {
        long long num = n - r + i;   // numerator part
        long long den = i;           // denominator part

        // reduce by their gcd before multiplying
        long long g = gcdll(num, den);
        num /= g;
        den /= g;

        // check for overflow: if result * num would overflow,
        // use double and cast back (works for n<=60; for very large n use big integers)
        if (result > LLONG_MAX / num) {
            cerr << "Warning: result may overflow 64‑bit integer.\n";
        }

        result *= num;
        result /= den;               // perfect division
    }
    return result;
}

//------------ main -------------------------------------------------
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, r;
    cout << "Enter n and r (space separated): ";
    if (!(cin >> n >> r)) {
        cerr << "Invalid input.\n";
        return 1;
    }

    if (r < 0 || r > n) {
        cout << "Invalid range: must have 0 ≤ r ≤ n.\n";
        return 0;
    }

    long long answer = nCr(n, r);
    cout << n << " choose " << r << " = " << answer << '\n';
    return 0;
}
```

### How the algorithm works

* **Symmetry** – `C(n,r) = C(n, n‑r)`.  We take the smaller of `r` and `n‑r` to reduce steps.
* **Term‑by‑term reduction** – We multiply the current result by the *next numerator* and immediately divide by the *next denominator*, after reducing each pair by their greatest common divisor.  
  This keeps the intermediate value as small as possible and guarantees that every division is exact.
* **Safety check** – If the intermediate product would exceed `LLONG_MAX`, a warning is printed. For workloads that exceed 64‑bit, replace the `long long` type with a big‑integer type.

