const double serviceCharge = 1.00; // service charge for the bank

class NCR {
private:
    double amountDue;
    double amountReceived;

public:
    // constructor
    NCR(double amountDue) {
        this->amountDue = amountDue;
    }

    // calculate change due if cash is given
    double calculateChange(double amountReceived) {
        if (amountReceived < amountDue) {
            std::cout << "Please provide more cash." << std::endl;
