        std::cout << "Receipt:" << std::endl;
        std::cout << "Amount Due: $" << amountDue << std::endl;
        std::cout << "Cash Provided: $" << amountReceived << std::endl;
        std::cout << "Service Charge: $" << serviceCharge << std::endl;
        std::cout << "Total Amount Received: $" << amountReceived << std::endl;
        if (changeDue >= 0) {
            std::cout << "Change Due: $" << changeDue << std::endl;
        }
    }
};

