    if (n < 0) {
        printf("Error! Factorial of a negative number doesn't exist.");
    } else {
        for (i = 1; i <= n; ++i) {
            factorial *= i; // multiply factorial by the current loop index
        }
        printf("Factorial of %d = %llu\n", n, factorial);
    }

    return 0;
}
```

---

### 2. Recursive Approach (Function calling itself)
This is the most "elegant" way and is often used in computer science theory to demonstrate how functions can call themselves.

```c
#include <stdio.h>

// Function declaration
unsigned long long factorial(int n);

int main() {
    int n;

    printf("Enter an integer: ");
    scanf("%d", &n);

    if (n < 0) {
        printf("Error! Factorial of a negative number doesn't exist.");
    } else {
        printf("Factorial of %d = %llu\n", n, factorial(n));
    }

    return 0;
}

// Recursive function definition
