    public static long calculateFactorial(int n) {
        if (n < 0) {
            System.out.println("Error: Number must be non-negative.");
            return -1;
        }

        long factorial = 1;
        for (int i = 1; i <= n; i++) {
            factorial *= i; // Same as factorial = factorial * i
        }
        return factorial;
