/**
 * Definition for singly-linked list node.
 * @param {Object} options
 * @param {any} options.val - The node’s value.
 * @param {Node|null} options.next - Reference to the next node.
 */
class ListNode {
  constructor({ val = null, next = null } = {}) {
    this.val = val;
    this.next = next;
  }
}

/**
 * Reverses a singly linked list.
 *
 * @param {ListNode|null} head - The head of the original list.
 * @returns {ListNode|null} The new head of the reversed list.
 */
function reverseLinkedList(head) {
  let prev = null;
  let current = head;

  while (current !== null) {
    const nextTemp = current.next; // Save next node
    current.next = prev;           // Reverse pointer
    prev = current;                // Move prev forward
    current = nextTemp;            // Move current forward
  }

  return prev; // New head
}
```

